// Bike builder: a popup with a live side view of the bike and the numbers that make it.
// Everything is generated by bikegen.js from the config, so what you see is what you ride.
import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { buildBike, solve, normalize, PRESETS, WHEELS } from './bikegen.js';
import { Suspension } from './suspension.js';
import { listBikes, saveBike, deleteBike, getBike, gameId } from './bikestore.js';

const CSS = `
#bb { position: fixed; inset: 0; z-index: 50; display: grid; place-items: center; background: rgba(8,18,26,.55);
      backdrop-filter: blur(4px); font-family: ui-rounded, "Segoe UI", system-ui, sans-serif; color: #fff; }
#bb * { box-sizing: border-box; }
#bb .card { width: min(1240px, calc(100vw - 32px)); height: min(780px, calc(100vh - 32px)); display: grid;
      grid-template-rows: auto 1fr auto; border-radius: 16px; overflow: hidden; background: rgba(16,30,40,.94);
      box-shadow: 0 20px 60px rgba(0,0,0,.4); }
#bb header, #bb footer { display: flex; align-items: center; gap: 10px; padding: 10px 14px; }
#bb header h2 { margin: 0; font-size: 17px; font-weight: 900; white-space: nowrap; }
#bb .name { flex: 1; min-width: 0; max-width: 320px; font: 800 15px/1 inherit; font-family: inherit; color: #fff; background: rgba(255,255,255,.1);
      border: 1px solid rgba(255,255,255,.18); border-radius: 8px; padding: 8px 10px; }
#bb .x { margin-left: auto; }
#bb button { font: 800 13px/1 inherit; font-family: inherit; color: #fff; background: rgba(255,255,255,.12); border: 0; border-radius: 8px;
      padding: 9px 12px; cursor: pointer; white-space: nowrap; }
#bb button:hover { background: rgba(255,255,255,.22); }
#bb button.go { background: #ffd21f; color: #1d2b64; }
#bb button.go:hover { background: #ffe066; }
#bb button.on { outline: 2px solid #ffd21f; }
#bb button.danger { background: transparent; color: #ff9a8a; }
#bb .body { display: grid; grid-template-columns: 1fr 360px; min-height: 0; }
#bb .view { position: relative; min-height: 0; background: linear-gradient(#d9ecf4, #bcd9e6); }
#bb .view canvas, #bb .view svg { position: absolute; inset: 0; width: 100%; height: 100%; }
#bb .view svg { pointer-events: none; font: 700 12px/1 ui-rounded, "Segoe UI", system-ui, sans-serif; }
#bb .viewbar { position: absolute; left: 12px; bottom: 10px; display: flex; gap: 8px; align-items: center; color: #1d2b64;
      font-weight: 800; font-size: 12px; background: rgba(255,255,255,.75); border-radius: 9px; padding: 6px 10px; }
#bb .warn { position: absolute; right: 12px; top: 10px; color: #8a2a10; background: #ffe7c2; border-radius: 8px; padding: 6px 10px;
      font-size: 12px; font-weight: 800; display: none; }
#bb .panel { overflow-y: auto; padding: 4px 14px 14px; border-left: 1px solid rgba(255,255,255,.08); }
#bb .chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0 4px; }
#bb .chips button { padding: 7px 10px; font-size: 12px; }
#bb h4 { margin: 12px 0 2px; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.55); }
#bb details { border-top: 1px solid rgba(255,255,255,.08); padding: 6px 0; }
#bb summary { cursor: pointer; font-weight: 900; font-size: 14px; padding: 4px 0; }
#bb .row { display: grid; grid-template-columns: 112px 1fr 58px; gap: 8px; align-items: center; padding: 4px 0; font-size: 13px; font-weight: 600; }
#bb .row.off { opacity: .35; pointer-events: none; }
#bb .row input[type=range] { width: 100%; accent-color: #ffd21f; }
#bb .row .val { text-align: right; font-variant-numeric: tabular-nums; color: rgba(255,255,255,.8); font-size: 12px; }
#bb .row select { grid-column: 2 / 4; font: 700 13px/1 inherit; font-family: inherit; padding: 6px; border-radius: 7px; border: 0; color: #1d2b64; }
#bb .row input[type=checkbox] { justify-self: start; width: 18px; height: 18px; accent-color: #ffd21f; }
#bb .row input[type=color] { grid-column: 2 / 4; width: 100%; height: 28px; border: 0; border-radius: 6px; background: none; padding: 0; }
#bb footer { border-top: 1px solid rgba(255,255,255,.08); flex-wrap: wrap; }
#bb .stats { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12px; font-weight: 700; color: rgba(255,255,255,.75); margin-right: auto; }
#bb .stats b { color: #fff; background: none; padding: 0; }
@media (max-width: 820px) {
  #bb .card { width: 100vw; height: 100vh; border-radius: 0; }
  #bb .body { grid-template-columns: 1fr; grid-template-rows: 42vh 1fr; }
  #bb .panel { border-left: 0; border-top: 1px solid rgba(255,255,255,.08); }
}`;

const R = (k, label, min, max, step, unit = 'mm', fmt) => ({ k, label, type: 'range', min, max, step, unit, fmt });
const S = (k, label, options) => ({ k, label, type: 'select', options });
const C = (k, label) => ({ k, label, type: 'check' });
const COL = (k, label) => ({ k, label, type: 'color' });
const WHEEL_OPTS = Object.keys(WHEELS).map(w => [w, `${w}"`]);
const SCHEMA = [
  ['Ride', [S('style', 'Ride feel', [['bmx', 'BMX: nimble, poppy'], ['dj', 'Dirt jump'], ['trail', 'Enduro'], ['dh', 'Downhill: planted, soft']]),
            S('type', 'Parts kit', [['bmx', 'BMX'], ['dj', 'Dirt jump'], ['trail', 'Trail / enduro'], ['dh', 'Downhill']])]],
  ['Wheels', [S('wheelF', 'Front wheel', WHEEL_OPTS), S('wheelR', 'Rear wheel', WHEEL_OPTS),
              R('tyreF', 'Front tyre', 1.8, 2.8, 0.05, '"', v => v.toFixed(2)), R('tyreR', 'Rear tyre', 1.8, 2.8, 0.05, '"', v => v.toFixed(2)),
              C('knobs', 'Knobbly tread'), C('discs', 'Disc brakes'), C('pegs', 'Pegs')]],
  ['Frame', [R('reach', 'Reach', 300, 540, 1), R('stack', 'Stack', 250, 700, 1),
             R('headAngle', 'Head angle', 60, 76, 0.1, '°', v => v.toFixed(1)), R('seatAngle', 'Seat angle', 66, 80, 0.1, '°', v => v.toFixed(1)),
             R('chainstay', 'Chainstay', 320, 480, 1), R('bbDrop', 'BB drop', -50, 50, 1),
             R('headTube', 'Head tube', 80, 180, 1), R('seatTube', 'Seat tube', 180, 520, 1),
             R('ttJoin', 'Top tube height', 0.5, 1, 0.01, '', v => `${Math.round(v * 100)}%`), R('tube', 'Tube size', 0.8, 1.6, 0.01, '×', v => v.toFixed(2)),
             R('saddle', 'Saddle height', 420, 820, 1)]],
  ['Fork & suspension', [S('fork', 'Fork', [['rigid', 'Rigid'], ['single', 'Suspension, single crown'], ['dual', 'Suspension, dual crown (DH)']]),
                         R('forkTravel', 'Fork travel', 80, 220, 5), R('forkOffset', 'Fork offset', 20, 65, 1),
                         S('rear', 'Rear', [['hardtail', 'Hardtail'], ['fourbar', 'Full suspension (four-bar)']]),
                         R('rearTravel', 'Rear travel', 100, 220, 5)]],
  ['Cockpit', [S('bar', 'Bar', [['bmx', 'BMX two-piece'], ['riser', 'Riser bar']]),
               R('barWidth', 'Bar width', 600, 820, 5), R('barRise', 'Bar rise', 0, 260, 5), R('stem', 'Stem length', 25, 80, 1)]],
  ['Drivetrain', [R('crank', 'Crank length', 150, 185, 2.5, 'mm', v => v.toFixed(1)), R('ring', 'Chainring', 22, 40, 1, 'T', v => v),
                  R('cog', 'Rear cog', 9, 42, 1, 'T', v => v)]],
  ['Colours', [COL('colors.frame', 'Frame'), COL('colors.fork', 'Fork'), COL('colors.rims', 'Rims'), COL('colors.parts', 'Parts'),
               COL('colors.tyres', 'Tyres'), COL('colors.spring', 'Shock spring')]],
];
const getK = (o, k) => k.split('.').reduce((a, b) => a?.[b], o);
const setK = (o, k, v) => { const ks = k.split('.'), last = ks.pop(); ks.reduce((a, b) => a[b], o)[last] = v; };

let open = null;
export function openBuilder({ editId = null, onRide } = {}) {
  if (open) return open;
  if (!document.getElementById('bb-css')) { const st = document.createElement('style'); st.id = 'bb-css'; st.textContent = CSS; document.head.appendChild(st); }
  let cfg = normalize(editId ? getBike(editId) : { ...PRESETS.dh, name: 'My downhill bike' });
  let curId = editId && getBike(editId) ? editId : null;
  let dirty = false;

  const root = document.createElement('div'); root.id = 'bb';
  root.innerHTML = `<div class="card">
    <header><h2>Bike builder</h2><input class="name" maxlength="28" spellcheck="false"><button class="x" title="Close (Esc)">✕</button></header>
    <div class="body">
      <div class="view"><canvas></canvas><svg></svg><div class="warn"></div>
        <div class="viewbar">Suspension <input class="squish" type="range" min="0" max="1" step="0.01" value="0"> <label><input class="dims" type="checkbox" checked> Dimensions</label></div></div>
      <div class="panel"><h4>Start from</h4><div class="chips presets"></div><h4>My bikes</h4><div class="chips mine"></div><div class="sections"></div></div>
    </div>
    <footer><div class="stats"></div><button class="danger del">Delete</button><button class="save">Save</button><button class="go ride">Save &amp; ride</button></footer>
  </div>`;
  document.body.appendChild(root);
  const $ = (s) => root.querySelector(s);
  const nameEl = $('.name'), view = $('.view'), canvas = $('canvas'), svg = $('svg'), warnEl = $('.warn');

  // ---- keys: the game must not see them while the builder is open ----
  dispatchEvent(new Event('blur'));   // the game releases any held keys on blur
  const swallow = (e) => {
    if (e.type === 'keydown' && e.code === 'Escape') { close(); }
    e.stopImmediatePropagation();
  };
  addEventListener('keydown', swallow, true); addEventListener('keyup', swallow, true);

  // ---- 3D side view ----
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(2, devicePixelRatio));
  renderer.toneMapping = THREE.NeutralToneMapping;
  const scene = new THREE.Scene();
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.7;
  const sun = new THREE.DirectionalLight(0xffffff, 1.6); sun.position.set(1, 3, 4); scene.add(sun);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x8899aa, 0.6));
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(6, 1.2), new THREE.MeshBasicMaterial({ color: 0x9fc2d2, transparent: true, opacity: 0.5 }));
  ground.rotation.x = -Math.PI / 2; ground.position.set(0.2, -0.001, 0); scene.add(ground);
  const cam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 20);
  cam.position.set(0, 0.5, 6); cam.lookAt(0, 0.5, 0);
  let bike = null, susp = null, geo = null, W = 1, H = 1;

  const disposeBike = () => {
    if (!bike) return;
    bike.traverse(o => { if (o.isMesh) { o.geometry.dispose(); o.material.dispose(); } });
    scene.remove(bike); bike = null;
  };
  const rebuild = () => {
    disposeBike();
    bike = buildBike(cfg, 'preview'); scene.add(bike);
    susp = bike.userData.suspension ? new Suspension(bike, bike.userData) : null;
    geo = solve(cfg);
    fit(); stats(); squish();
    const warn = [];
    if (geo.L < 0.32 && cfg.fork !== 'rigid') warn.push('Fork is very short for this stack and wheel: raise the stack or use a smaller wheel');
    if (geo.dims.bbHeight < Math.max(geo.RF, geo.RR) * 0.72) warn.push('BB is very low: pedals will strike');
    warnEl.style.display = warn.length ? 'block' : 'none'; warnEl.textContent = warn.join(' · ');
  };
  const fit = () => {
    const r = view.getBoundingClientRect(); W = Math.max(1, r.width); H = Math.max(1, r.height);
    renderer.setSize(W, H, false);
    const x0 = geo.A.x - geo.RR - 0.12, x1 = geo.F.x + geo.RF + 0.12, y0 = -0.17, y1 = Math.max(geo.saddle.y, geo.htTop.y + cfg.barRise / 1000) + 0.12;
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    let hw = (x1 - x0) / 2, hh = (y1 - y0) / 2;
    if (hw / hh > W / H) hh = hw * H / W; else hw = hh * W / H;
    Object.assign(cam, { left: cx - hw, right: cx + hw, top: cy + hh, bottom: cy - hh });
    cam.position.set(0, 0, 6); cam.lookAt(0, 0, 0); cam.updateProjectionMatrix();
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  };
  const scr = (x, y) => { const v = new THREE.Vector3(x, y, 0).project(cam); return [(v.x + 1) / 2 * W, (1 - v.y) / 2 * H]; };
  const drawDims = () => {
    if (!$('.dims').checked || +$('.squish').value > 0) { svg.innerHTML = ''; return; }
    const g = geo, out = [];
    const line = (a, b, label, lx, ly, anchor = 'middle') => {
      const [x0, y0] = scr(...a), [x1, y1] = scr(...b), [tx, ty] = scr(lx, ly);
      out.push(`<line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y1}" stroke="#1d2b64" stroke-width="1.5" marker-start="url(#ar)" marker-end="url(#ar)"/>`,
               `<text x="${tx}" y="${ty}" text-anchor="${anchor}" fill="#1d2b64" paint-order="stroke" stroke="#e2f0f6" stroke-width="4">${label}</text>`);
    };
    const mm = (v) => Math.round(v * 1000);
    line([g.A.x, -0.07], [g.F.x, -0.07], `Wheelbase ${mm(g.dims.wheelbase)}`, (g.A.x + g.F.x) / 2, -0.11);
    line([g.BB.x, g.htTop.y + 0.07], [g.htTop.x, g.htTop.y + 0.07], `Reach ${cfg.reach}`, g.BB.x - 0.02, g.htTop.y + 0.085, 'end');
    line([g.htTop.x + 0.09, g.BB.y], [g.htTop.x + 0.09, g.htTop.y], `Stack ${cfg.stack}`, g.htTop.x + 0.11, (g.BB.y + g.htTop.y) / 2, 'start');
    line([g.BB.x, 0], [g.BB.x, g.BB.y], `BB ${mm(g.BB.y)}`, g.BB.x + 0.02, g.BB.y * 0.35, 'start');
    line([g.A.x, g.A.y - 0.0], [g.BB.x, g.BB.y], '', 0, 0);
    { const [tx, ty] = scr((g.A.x + g.BB.x) / 2, (g.A.y + g.BB.y) / 2 - 0.035); out.push(`<text x="${tx}" y="${ty}" text-anchor="middle" fill="#1d2b64" paint-order="stroke" stroke="#e2f0f6" stroke-width="4">CS ${cfg.chainstay}</text>`); }
    // steer axis to the ground: trail
    const t = g.htTop.y / g.axis.y, gx = g.htTop.x - g.axis.x * t;
    const [a0, a1] = scr(g.htTop.x + g.axis.x * 0.05, g.htTop.y + g.axis.y * 0.05), [b0, b1] = scr(gx, 0);
    out.push(`<line x1="${a0}" y1="${a1}" x2="${b0}" y2="${b1}" stroke="#1d2b64" stroke-width="1" stroke-dasharray="5 4" opacity=".6"/>`);
    const [hx, hy] = scr(g.htBot.x + 0.04, g.htBot.y - 0.02); out.push(`<text x="${hx}" y="${hy}" fill="#1d2b64" paint-order="stroke" stroke="#e2f0f6" stroke-width="4">HA ${cfg.headAngle.toFixed(1)}°</text>`);
    const [sx, sy] = scr(g.stTop.x - 0.04, g.stTop.y - 0.05); out.push(`<text x="${sx}" y="${sy}" text-anchor="end" fill="#1d2b64" paint-order="stroke" stroke="#e2f0f6" stroke-width="4">SA ${cfg.seatAngle.toFixed(1)}°</text>`);
    svg.innerHTML = `<defs><marker id="ar" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 2 L10 5 L0 8 z" fill="#1d2b64"/></marker></defs>${out.join('')}`;
  };
  const stats = () => {
    const d = geo.dims, mm = (v) => Math.round(v * 1000);
    $('.stats').innerHTML = `<span>Wheelbase <b>${mm(d.wheelbase)}</b></span><span>Front centre <b>${mm(d.frontCenter)}</b></span>
      <span>BB height <b>${mm(d.bbHeight)}</b></span><span>Trail <b>${mm(d.trail)}</b></span><span>Fork A–C <b>${mm(d.forkLength)}</b></span>
      <span>Triangles <b>${(bike.userData.tris / 1000).toFixed(1)}k</b></span>`;
  };
  const squish = () => {
    if (!susp) return;
    const k = +$('.squish').value;   // 0 = standing at sag .. 1 = bottomed out
    susp.xF = susp.F.max * k; susp.xR = susp.R.max * k;
    susp.apply();
  };
  $('.squish').addEventListener('input', () => { squish(); drawDims(); });
  $('.dims').addEventListener('change', drawDims);
  const ro = new ResizeObserver(() => { if (geo) { fit(); drawDims(); } }); ro.observe(view);
  let raf = 0;
  const loop = () => { raf = requestAnimationFrame(loop); renderer.render(scene, cam); };

  // ---- panel ----
  const chips = (el, items) => {
    el.innerHTML = '';
    for (const [label, fn, on] of items) { const b = document.createElement('button'); b.textContent = label; if (on) b.className = 'on'; b.onclick = fn; el.appendChild(b); }
  };
  const refreshMine = () => chips($('.mine'), listBikes().length ? listBikes().map(b => [b.name || 'Bike', () => load(b.id), b.id === curId])
    : [['+ none yet: build one and Save', () => {}]]);
  chips($('.presets'), Object.entries(PRESETS).map(([k, pr]) => [pr.name, () => {
    if (dirty && !confirm('Start again from the preset? Unsaved changes are lost.')) return;
    cfg = normalize({ ...PRESETS[k], name: `My ${pr.name.toLowerCase()}` }); curId = null; dirty = false; sync(); refreshMine();
  }]));
  const load = (id) => {
    if (dirty && id !== curId && !confirm('Open another bike? Unsaved changes are lost.')) return;
    cfg = normalize(getBike(id)); curId = id; dirty = false; sync(); refreshMine();
  };
  const sections = $('.sections'), inputs = [];
  for (const [title, fields] of SCHEMA) {
    const det = document.createElement('details'); det.open = title !== 'Colours';
    det.innerHTML = `<summary>${title}</summary>`;
    for (const f of fields) {
      const row = document.createElement('div'); row.className = 'row';
      row.innerHTML = `<span>${f.label}</span>`;
      let inp, val;
      if (f.type === 'range') {
        inp = Object.assign(document.createElement('input'), { type: 'range', min: f.min, max: f.max, step: f.step });
        val = document.createElement('span'); val.className = 'val';
        row.append(inp, val);
      } else if (f.type === 'select') {
        inp = document.createElement('select');
        for (const [v, l] of f.options) inp.add(new Option(l, v));
        row.append(inp);
      } else if (f.type === 'check') {
        inp = Object.assign(document.createElement('input'), { type: 'checkbox' }); row.append(inp);
      } else {
        inp = Object.assign(document.createElement('input'), { type: 'color' }); row.append(inp);
      }
      const read = () => f.type === 'range' ? +inp.value : f.type === 'check' ? inp.checked : inp.value;
      inp.addEventListener(f.type === 'range' || f.type === 'color' ? 'input' : 'change', () => {
        setK(cfg, f.k, read()); dirty = true; showVal(); availability(); schedule();
      });
      const showVal = () => { if (val) val.textContent = (f.fmt ? f.fmt(+inp.value) : inp.value) + (f.unit === 'mm' || !f.unit ? '' : f.unit); };
      inputs.push({ f, inp, row, showVal, set: (v) => { if (f.type === 'check') inp.checked = !!v; else inp.value = v; showVal(); } });
      det.appendChild(row);
    }
    sections.appendChild(det);
  }
  const availability = () => {
    for (const it of inputs) {
      const off = (it.f.k === 'forkTravel' && cfg.fork === 'rigid') || (it.f.k === 'rearTravel' && cfg.rear !== 'fourbar')
        || (it.f.k === 'colors.spring' && cfg.rear !== 'fourbar');
      it.row.classList.toggle('off', off);
    }
  };
  let pending = false;
  const schedule = () => { if (pending) return; pending = true; requestAnimationFrame(() => { pending = false; rebuild(); drawDims(); }); };
  const sync = () => {
    nameEl.value = cfg.name || '';
    for (const it of inputs) it.set(getK(cfg, it.f.k));
    $('.squish').value = 0;
    availability(); rebuild(); drawDims();
    $('.del').style.visibility = curId ? 'visible' : 'hidden';
  };
  nameEl.addEventListener('input', () => { cfg.name = nameEl.value; dirty = true; });

  // ---- actions ----
  const save = () => {
    cfg.name = (nameEl.value || '').trim() || 'My bike'; nameEl.value = cfg.name;
    const { id, ...rest } = cfg;
    curId = saveBike({ ...rest, id: curId || undefined }); dirty = false; refreshMine();
    $('.del').style.visibility = 'visible';
    return curId;
  };
  $('.save').onclick = () => { save(); flashBtn($('.save'), 'Saved ✓'); };
  $('.ride').onclick = () => { const id = save(); close(); onRide?.(gameId(id)); };
  $('.del').onclick = () => {
    if (!curId || !confirm(`Delete “${cfg.name}”? This can't be undone.`)) return;
    deleteBike(curId); curId = null; dirty = false; refreshMine(); $('.del').style.visibility = 'hidden';
  };
  const flashBtn = (b, t) => { const o = b.textContent; b.textContent = t; setTimeout(() => (b.textContent = o), 1200); };
  $('.x').onclick = () => close();
  root.addEventListener('pointerdown', (e) => { if (e.target === root) close(); });

  function close() {
    if (dirty && !confirm('Close without saving?')) return;
    cancelAnimationFrame(raf); ro.disconnect();
    removeEventListener('keydown', swallow, true); removeEventListener('keyup', swallow, true);
    disposeBike(); pmrem.dispose(); renderer.dispose(); renderer.forceContextLoss();
    root.remove(); open = null;
  }

  refreshMine(); sync(); loop();
  open = { close };
  return open;
}
